output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_into_single_file_aisle",
    "text": "A customer must not move a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_shelf_aisle_with_cart"
    }
  },
  {
    "id": "retrieve_parked_cart_from_upper_aisle_bay",
    "text": "If a customer parks a cart at an upper-aisle cart bay, they are obliged to retrieve it before leaving.",
    "abstraction": {
      "state_properties": {
        "upper_aisle_cart_bay": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {
        "park_cart_at_upper_aisle_bay": {
          "pre": {
            "and": [
              "hasCart",
              "upper_aisle_cart_bay",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart_at_upper_aisle_bay": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "upper_aisle_cart_bay",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart_at_upper_aisle_bay",
      "discharge": "retrieve_cart_at_upper_aisle_bay"
    }
  },
  {
    "id": "return_to_cart_after_hand_pick",
    "text": "After collecting an item by hand in a single-file shelf aisle, the customer must return to a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "hand_pick_in_single_file_aisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "single_file_shelf_aisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "hand_pick_in_single_file_aisle",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_cartless_wandering",
    "text": "Customers may be without their cart only at the entrance cart rack or in the narrow-aisle service area.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_rack": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "upper_aisle_cart_bay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "permitted_cartless_area": {
          "or": [
            "entrance_cart_rack",
            "single_file_shelf_aisle",
            "upper_aisle_cart_bay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "permitted_cartless_area"
          }
        ]
      }
    }
  },
  {
    "id": "park_only_at_upper_aisle_bays",
    "text": "A customer may park or drop a cart only at the designated upper-aisle cart bays.",
    "abstraction": {
      "state_properties": {
        "upper_aisle_cart_bay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "drop_cart_away_from_upper_aisle_bay": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "upper_aisle_cart_bay"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "drop_cart_away_from_upper_aisle_bay"
    }
  },
  {
    "id": "cart_required_for_ordinary_shelf_service",
    "text": "At ordinary shelf fronts outside single-file aisles, shelf interaction is forbidden unless the customer has a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "ordinary_shelf_front": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "ordinary_shelf_front",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_westbound_travel",
    "text": "The store aisles are one-way, so westbound movement is forbidden.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  }
]
